15	} from '@mantine/core';
16	import { useForm } from '@mantine/form';
17	import { notifications } from '@mantine/notifications';
18	import {
19	    IconAlertTriangle,
20	    IconCheck,
21	    IconChevronLeft,
22	    IconChevronRight,
23	} from '@tabler/icons-react';
24	import { zod4Resolver } from 'mantine-form-zod-resolver';
25	import { useRouter } from 'next/navigation';
26	import { useState } from 'react';
27	import z from 'zod';
28	
29	import { config } from '@/lib/config';
30	import { formatDate, getFullMonthName, getShortMonthName } from '@/lib/dates';
31	import { toPounds } from '@/lib/money';
32	import { captureUnexpectedError } from '@/lib/observability/sentry';
33	import type { RecordHallHireProxy } from '@/types/actions/RecordHallHire';
34	import type { UpdateInvoiceGameDaysProxy } from '@/types/actions/UpdateInvoiceGameDays';
35	
36	const InvoiceFormSchema = z.object({
37	    gameDays: z.array(
38	        z.object({
39	            id: z.number().int().positive(),
40	            gameScheduled: z.boolean(),
41	            hallCostPounds: z.number().min(0),
42	        }),
43	    ),
44	});
45	
46	type InvoiceFormValues = z.infer<typeof InvoiceFormSchema>;
47	
48	// Breakpoint at which the submit button switches from a full-width mobile
49	// touch target to an inline fit-content button.
50	const actionsBreakpoint = 'sm';
51	
52	interface GameDayRow {
53	    id: number;
54	    date: string;
55	    gameScheduled: boolean;
56	    hallCost: number;
57	}
58	
59	interface InvoiceFormProps {
60	    year: number;
61	    month: number;
62	    gameDays: GameDayRow[];
63	    onUpdateGameDays: UpdateInvoiceGameDaysProxy;
64	    onRecordHallHire: RecordHallHireProxy;
65	}
66	
67	export const InvoiceForm = ({
68	    year,
69	    month,
70	    gameDays,
71	    onUpdateGameDays,
72	    onRecordHallHire,
73	}: InvoiceFormProps) => {
74	    const router = useRouter();
75	    const [submitting, setSubmitting] = useState(false);
76	
77	    const form = useForm<InvoiceFormValues>({
78	        initialValues: {
79	            gameDays: gameDays.map((gd) => ({
80	                id: gd.id,
81	                gameScheduled: gd.gameScheduled,
82	                /* c8 ignore next — hallCost is a non-nullable DB column; the ?? 0 is a runtime safety net only */
83	                hallCostPounds: toPounds(gd.hallCost ?? 0),
84	            })),
85	        },
86	        validate: zod4Resolver(InvoiceFormSchema),
87	    });
88	
89	    const navigateMonth = (delta: number) => {
90	        let newMonth = month + delta;
91	        let newYear = year;
92	        if (newMonth < 1) {
93	            newMonth = 12;
94	            newYear -= 1;
95	        }
96	        if (newMonth > 12) {
97	            newMonth = 1;
98	            newYear += 1;
99	        }
100	        router.push(`/footy/admin/invoice?year=${newYear}&month=${newMonth}`);
101	    };
102	
103	    const handleSubmit = async (values: InvoiceFormValues) => {
104	        const notificationId = 'invoice-form';
105	
106	        notifications.show({
107	            id: notificationId,
108	            loading: true,
109	            title: 'Saving invoice',
110	            message: 'Saving game days and recording hall hire...',
111	            autoClose: false,
112	            withCloseButton: false,
113	        });
114	
115	        setSubmitting(true);
116	        try {
117	            await onUpdateGameDays({
118	                gameDays: values.gameDays.map((gd) => ({
119	                    id: gd.id,
120	                    gameScheduled: gd.gameScheduled,
121	                })),
122	            });
123	
124	            await Promise.all(
125	                values.gameDays
126	                    .filter((gd) => gd.gameScheduled && gd.hallCostPounds > 0)
127	                    .map((gd) =>
128	                        onRecordHallHire({
129	                            amountPence: Math.round(gd.hallCostPounds * 100),
130	                            gameDayId: gd.id,
131	                            note: `Kelsey Kerridge invoice ${getFullMonthName(year, month)} ${year}`,
132	                        }),
133	                    ),
134	            );
135	
136	            const total = values.gameDays
137	                .filter((gd) => gd.gameScheduled)
138	                .reduce((sum, gd) => sum + gd.hallCostPounds, 0);
139	
140	            notifications.update({
141	                id: notificationId,
142	                color: 'teal',
143	                title: 'Invoice recorded',
144	                message: `Hall hire of £${total.toFixed(2)} recorded.`,
145	                icon: <IconCheck size={config.notificationIconSize} />,
146	                loading: false,
147	                autoClose: config.notificationAutoClose,
148	            });
149	        } catch (err) {
150	            captureUnexpectedError(err, {
151	                layer: 'client',
152	                component: 'InvoiceForm',
153	                action: 'submit',
154	                route: '/footy/admin/invoice',
155	            });
156	            notifications.update({
157	                id: notificationId,
158	                color: 'red',
159	                title: 'Error',
160	                message:
161	                    err instanceof Error
162	                        ? err.message
163	                        : 'Failed to save invoice.',
164	                icon: <IconAlertTriangle size={config.notificationIconSize} />,
165	                loading: false,
166	                autoClose: false,
167	                withCloseButton: true,
168	            });
169	        } finally {
170	            setSubmitting(false);
171	        }
172	    };
173	
174	    const total = form.values.gameDays
175	        .filter((gd) => gd.gameScheduled)
176	        .reduce((sum, gd) => sum + (gd.hallCostPounds || 0), 0);
177	
178	    return (
179	        <Paper
180	            maw="30rem"
181	            mx="auto"
182	            my="lg"
183	        >
184	            <Stack gap="md">
185	                <Title order={2}>Invoice Check</Title>
186	
187	                <Group
188	                    justify="space-between"
189	                    wrap="wrap"
190	                >
191	                    <Button
192	                        variant="subtle"
193	                        leftSection={<IconChevronLeft size={16} />}
194	                        onClick={() => navigateMonth(-1)}
195	                    >
196	                        {getShortMonthName(year, month - 1)}
197	                    </Button>
198	                    <Title
199	                        order={3}
200	                        flex={1}
201	                        ta="center"
202	                    >
203	                        {getShortMonthName(year, month)} {year}
204	                    </Title>
205	                    <Button
206	                        variant="subtle"
207	                        rightSection={<IconChevronRight size={16} />}
208	                        onClick={() => navigateMonth(1)}
209	                    >
210	                        {getShortMonthName(year, month + 1)}
211	                    </Button>
212	                </Group>
213	
214	                {gameDays.length === 0 ? (
215	                    <Text c="dimmed">No game days found for this month.</Text>
216	                ) : (
217	                    <Box
218	                        component="form"
219	                        onSubmit={form.onSubmit(handleSubmit)}
220	                    >
221	                        <Stack gap="sm">
222	                            {gameDays.map((gd, index) => (
223	                                <Flex
224	                                    key={gd.id}
225	                                    wrap="wrap"
226	                                    align="center"
227	                                    gap="sm"
228	                                    bd="1px solid var(--mantine-color-gray-3)"
229	                                    p="sm"
230	                                    bdrs="sm"
231	                                >
232	                                    <Text
233	                                        fw={600}
234	                                        miw="7rem"
235	                                    >
236	                                        {formatDate(gd.date)}
237	                                    </Text>
238	                                    <Checkbox
239	                                        label="Game"
240	                                        aria-label={`Game scheduled for ${formatDate(gd.date)}`}
241	                                        {...form.getInputProps(
242	                                            `gameDays.${index}.gameScheduled`,
243	                                            { type: 'checkbox' },
244	                                        )}
245	                                    />
246	                                    <NumberInput
247	                                        aria-label={`Hall cost for ${formatDate(gd.date)}`}
248	                                        prefix="£"
249	                                        decimalScale={2}
250	                                        disabled
251	                                        fixedDecimalScale
252	                                        allowNegative={false}
253	                                        hideControls
254	                                        min={0}
255	                                        w="6rem"
256	                                        ml="auto"
257	                                        {...form.getInputProps(
258	                                            `gameDays.${index}.hallCostPounds`,
259	                                        )}
260	                                    />
261	                                </Flex>
262	                            ))}
263	
264	                            <Divider />
265	
266	                            <Group
267	                                justify="space-between"
268	                                align="center"
269	                                wrap="wrap"
270	                            >
271	                                <Text fw={600}>Total: £{total.toFixed(2)}</Text>
272	                                <Button
273	                                    type="submit"
274	                                    w={{
275	                                        base: '100%',
276	                                        [actionsBreakpoint]: 'fit-content',
277	                                    }}
278	                                    loading={submitting}
279	                                >
280	                                    Record invoice
281	                                </Button>
282	                            </Group>
283	                        </Stack>
284	                    </Box>
285	                )}
286	            </Stack>
287	        </Paper>
288	    );
289	};
