1	import { recordHallHire } from '@/actions/recordHallHire';
2	import { updateInvoiceGameDays } from '@/actions/updateInvoiceGameDays';
3	import { AutoRefresh } from '@/components/AutoRefresh/AutoRefresh';
4	import { InvoiceForm } from '@/components/InvoiceForm/InvoiceForm';
5	import { formatDate } from '@/lib/dates';
6	import { isGame } from '@/lib/gameResult';
7	import gameDayService from '@/services/GameDay';
8	import { FootyChannel } from '@/types/FootyChannel';
9	
10	export const metadata = { title: 'Invoice Check' };
11	
12	interface InvoicePageProps {
13	    searchParams: Promise<{ year?: string; month?: string }>;
14	}
15	
16	const InvoicePage = async ({ searchParams }: InvoicePageProps) => {
17	    const params = await searchParams;
18	
19	    const now = new Date();
20	    // Default to next month since the invoice covers the coming month's bookings
21	    const nextMonth = new Date(now.getFullYear(), now.getMonth() + 1, 1);
22	
23	    const year = params.year
24	        ? parseInt(params.year, 10)
25	        : nextMonth.getFullYear();
26	    const month = params.month
27	        ? parseInt(params.month, 10)
28	        : nextMonth.getMonth() + 1;
29	
30	    const gameDaysRaw = await gameDayService.getForMonth(year, month);
31	
32	    // A game day is considered to have a game scheduled if its status isn't
33	    // NoGame, or if the invitations were sent (mailSent is not null).
34	    const gameDays = gameDaysRaw.map((gd) => ({
35	        id: gd.id,
36	        date: formatDate(gd.date),
37	        gameScheduled: isGame(gd.status) || gd.mailSent !== null,
38	        hallCost: gd.hallCost,
39	    }));
40	
41	    return (
42	        <>
43	            <AutoRefresh channels={[FootyChannel.Games, FootyChannel.Money]} />
44	            <InvoiceForm
45	                year={year}
46	                month={month}
47	                gameDays={gameDays}
48	                onUpdateGameDays={updateInvoiceGameDays}
49	                onRecordHallHire={recordHallHire}
50	            />
51	        </>
52	    );
53	};
54	
55	export default InvoicePage;
