19	import { useForm } from '@mantine/form';
20	import { useMounted } from '@mantine/hooks';
21	import { notifications } from '@mantine/notifications';
22	import { IconAlertTriangle, IconCheck } from '@tabler/icons-react';
23	import { zod4Resolver } from 'mantine-form-zod-resolver';
24	import { PlayerResponse } from 'prisma/generated/enums';
25	import { useState } from 'react';
26	import z from 'zod';
27	
28	import { config } from '@/lib/config';
29	import { captureUnexpectedError } from '@/lib/observability/sentry';
30	import {
31	    InvitationResponseInputSchema,
32	    SubmitGameInvitationResponseProxy,
33	} from '@/types/actions/SubmitGameInvitationResponse';
34	import { GameInvitationResponseDetails } from '@/types/GameInvitationResponseDetails';
35	
36	const formSchema = InvitationResponseInputSchema.omit({ token: true }).extend({
37	    comment: z.string().max(127).optional(),
38	});
39	type FormValues = z.infer<typeof formSchema>;
40	
41	const responseOptions = [
42	    { value: PlayerResponse.Yes, label: 'Yes' },
43	    { value: PlayerResponse.No, label: 'No' },
44	    { value: PlayerResponse.Dunno, label: 'Dunno' },
45	];
46	
47	/**
48	 * Responses that players can select themselves in this form.
49	 */
50	const playerEditableResponses = new Set<PlayerResponse>([
51	    PlayerResponse.Yes,
52	    PlayerResponse.No,
53	    PlayerResponse.Dunno,
54	]);
55	
56	/**
57	 * Returns the initial response value used by the editable select input.
58	 *
59	 * Player invitations can carry admin-only response values (for example
60	 * `Excused`) that should still be displayed in the summary, but players can
61	 * only submit Yes/No/Dunno from this form.
62	 *
63	 * @param response - Incoming invitation response from query details.
64	 * @returns The player-editable response value for the form select.
65	 */
66	function getInitialPlayerResponse(
67	    responseInput: GameInvitationResponseDetails['response'],
68	) {
69	    const response =
70	        responseInput && playerEditableResponses.has(responseInput)
71	            ? responseInput
72	            : PlayerResponse.Yes;
73	
74	    return response;
75	}
76	
77	interface Props {
78	    details: GameInvitationResponseDetails;
79	    onSubmitGameInvitationResponse: SubmitGameInvitationResponseProxy;
80	}
81	
82	export const GameInvitationResponseForm = ({
83	    details,
84	    onSubmitGameInvitationResponse,
85	}: Props) => {
86	    const mounted = useMounted();
87	    const response = getInitialPlayerResponse(details.response);
88	    const [currentResponse, setCurrentResponse] = useState(details.response);
89	    const [currentComment, setCurrentComment] = useState(details.comment);
90	    const [canSubmitWithoutChanges, setCanSubmitWithoutChanges] = useState(
91	        !details.response,
92	    );
93	    const [submitting, setSubmitting] = useState(false);
94	
95	    const form = useForm<FormValues>({
96	        initialValues: {
97	            response,
98	            goalie: details.goalie ?? false,
99	            comment: details.comment ?? '',
100	        },
101	        validate: zod4Resolver(formSchema),
102	        validateInputOnBlur: true,
103	    });
104	
105	    /**
106	     * The form is dirty if the user has changed a field, or if there is no
107	     * saved response yet. In that case, submission is allowed without
108	     * interaction so users can quickly confirm the default Yes value. Once a
109	     * response has been saved, the button should disable again until the form
110	     * changes.
111	     */
112	    const isFormDirty = form.isDirty() || canSubmitWithoutChanges;
113	
114	    const handleSubmit = async (values: FormValues) => {
115	        const id = notifications.show({
116	            loading: true,
117	            title: 'Saving response',
118	            message: 'Saving your response...',
119	            autoClose: false,
120	            withCloseButton: false,
121	        });
122	
123	        setSubmitting(true);
124	        try {
125	            await onSubmitGameInvitationResponse({
126	                token: details.token,
127	                response: values.response,
128	                goalie: values.goalie,
129	                comment: values.comment?.trim() ?? null,
130	            });
131	
132	            setCurrentResponse(values.response);
133	            setCurrentComment(values.comment?.trim() ?? '');
134	            setCanSubmitWithoutChanges(false);
135	
136	            notifications.update({
137	                id,
138	                color: 'teal',
139	                title: 'Response saved',
140	                message: 'Your response has been updated.',
141	                icon: <IconCheck size={config.notificationIconSize} />,
142	                loading: false,
143	                autoClose: config.notificationAutoClose,
144	            });
145	        } catch (error) {
146	            captureUnexpectedError(error, {
147	                layer: 'client',
148	                component: 'GameInvitationResponseForm',
149	                action: 'submitResponse',
150	                route: '/footy/game/[id]',
151	                extra: {
152	                    playerId: details.playerId,
153	                    gameDayId: details.gameDayId,
154	                    response: values.response,
155	                },
156	            });
157	            const message =
158	                error instanceof Error
159	                    ? error.message
160	                    : 'Failed to save response';
161	            notifications.update({
162	                id,
163	                color: 'red',
164	                title: 'Error',
165	                message,
166	                icon: <IconAlertTriangle size={config.notificationIconSize} />,
167	                loading: false,
168	                autoClose: false,
169	                withCloseButton: true,
170	            });
171	        } finally {
172	            setSubmitting(false);
173	        }
174	    };
175	
176	    const responseColor = {
177	        [PlayerResponse.Yes.toString()]: 'green',
178	        [PlayerResponse.No.toString()]: 'red',
179	        [PlayerResponse.Dunno.toString()]: 'grey',
180	    } as const;
181	    const displayResponse = currentResponse ? (
182	        <Badge
183	            color={responseColor[currentResponse.toString()]}
184	            variant="filled"
185	            size="sm"
186	        >
187	            {currentResponse}
188	        </Badge>
189	    ) : (
190	        <Badge
191	            color="grey"
192	            variant="filled"
193	            size="sm"
194	        >
195	            No response yet
196	        </Badge>
197	    );
198	    const displayComment = currentComment ? `("${currentComment}")` : '';
199	    const playerLink = details.playerLogin
200	        ? `/footy/player/${details.playerLogin}`
201	        : `/footy/player/${details.playerId}`;
202	
203	    return (
204	        <Paper
205	            w="100%"
206	            maw="35rem"
207	            mx="auto"
208	        >
209	            <Box
210	                component="form"
211	                onSubmit={form.onSubmit(handleSubmit)}
212	            >
213	                <Stack gap="md">
214	                    <Title
215	                        order={2}
216	                        mb="xs"
217	                        w="100%"
218	                        ta="center"
219	                    >
220	                        {currentResponse
221	                            ? 'Thanks for Your Response'
222	                            : 'Enter Your Response'}
223	                    </Title>
224	                    <Divider mb="xs" />
225	                    <Flex
226	                        align="center"
227	                        gap="md"
228	                        wrap="wrap"
229	                    >
230	                        <Avatar
231	                            src={`/api/footy/player/${details.playerId}/mugshot`}
232	                            alt={details.playerName}
233	                            size={48}
234	                            radius="xl"
235	                        />
236	                        <Anchor href={playerLink}>{details.playerName}</Anchor>:{' '}
237	                        {displayResponse} {displayComment}
238	                    </Flex>
239	                    <Select
240	                        label="Response"
241	                        data={responseOptions}
242	                        value={form.values.response}
243	                        /* v8 ignore next -- allowDeselect={false} means value is never null */
244	                        onChange={(value) =>
245	                            form.setFieldValue(
246	                                'response',
247	                                value ?? PlayerResponse.Yes,
248	                            )
249	                        }
250	                        allowDeselect={false}
251	                    />
252	                    <Checkbox
253	                        label="Goalie"
254	                        {...form.getInputProps('goalie', { type: 'checkbox' })}
255	                    />
256	                    <TextInput
257	                        label="Optional comment/excuse"
258	                        maxLength={127}
259	                        {...form.getInputProps('comment')}
260	                    />
261	                    <Button
262	                        type="submit"
263	                        w="fit-content"
264	                        loading={!mounted || submitting}
265	                        disabled={!isFormDirty}
266	                    >
267	                        Save Response
268	                    </Button>
269	                    <Text mt="xl">
270	                        You can change it later if you need to, even if the
271	                        teams have been picked - either by clicking on the link
272	                        in the email you received, or by logging in to the site
273	                        at{' '}
274	                        <Anchor href={`/footy/game/${details.gameDayId}`}>
275	                            the game page
276	                        </Anchor>
277	                        . If you can&apos;t get to a computer, message Jon on{' '}
278	                        <strong>{config.organiserPhoneNumber}</strong>.
279	                    </Text>
280	                </Stack>
281	            </Box>
282	        </Paper>
283	    );
284	};
