1	import prisma from 'prisma/prisma';
2	import {
3	    GameDayStatus,
4	    GameDayWhereInputObjectSchema,
5	    GameDayWhereUniqueInputObjectSchema,
6	    TeamName,
7	} from 'prisma/zod/schemas';
8	import { GameDayType } from 'prisma/zod/schemas/models/GameDay.schema';
9	
10	import { isPrismaNotFoundError } from '@/lib/prismaErrors';
11	import {
12	    GameDayCreateOneStrictSchema,
13	    type GameDayUpdateInput,
14	    GameDayUpdateInputSchema,
15	    GameDayUpdateOneStrictSchema,
16	    type GameDayUpsertInput,
17	    GameDayUpsertInputSchema,
18	    GameDayUpsertOneStrictSchema,
19	    type GameDayWriteInput,
20	    GameDayWriteInputSchema,
21	} from '@/types/GameDayStrictSchema';
22	
23	class GameDayService {
24	    /**
25	     * Retrieves a GameDayWithOutcomesWithPlayers by its ID.
26	     * @param id - The ID of the GameDay to retrieve.
27	     * @returns A Promise that resolves to the GameDay object if found, or null
28	     * if not found.
29	     */
30	    async get(id: number): Promise<GameDayType | null> {
31	        const where = GameDayWhereUniqueInputObjectSchema.parse({ id });
32	        return prisma.gameDay.findUnique({ where });
33	    }
34	
35	    /**
36	     * Retrieves all game days based on the provided filters, sorted by date
37	     * ascending then ID ascending.
38	     *
39	     * @param {Object} filters - The filters to apply when retrieving game days.
40	     * @param {TeamNameType} [filters.bibs] - The team name or bibs to filter by. If "null", it will be treated as null.
41	     * @param {GameDayStatus} [filters.status] - The status to filter by.
42	     * @param {boolean} [filters.mailSent] - Whether to filter by mail sent status. If true, it will filter for non-null mailSent values.
43	     * @param {number} [filters.year] - The year to filter by.
44	     * @param {Date} [filters.fromDate] - Only return game days on or after this date (inclusive).
45	     * @param {Date} [filters.beforeDate] - Only return game days before this date (exclusive).
46	     * @returns {Promise<GameDayType[]>} A promise that resolves to an array of GameDayType objects.
47	     */
48	    async getAll({
49	        bibs,
50	        status,
51	        mailSent,
52	        year,
53	        fromDate,
54	        beforeDate,
55	    }: {
56	        bibs?: TeamName;
57	        status?: GameDayStatus;
58	        mailSent?: boolean;
59	        year?: number;
60	        fromDate?: Date;
61	        beforeDate?: Date;
62	    } = {}): Promise<GameDayType[]> {
63	        const where = GameDayWhereInputObjectSchema.parse({
64	            bibs,
65	            status,
66	            year: year === 0 ? undefined : year,
67	        });
68	        if (mailSent !== undefined) {
69	            where.mailSent = mailSent ? { not: null } : null;
70	        }
71	        if (fromDate !== undefined || beforeDate !== undefined) {
72	            where.date = {
73	                ...(fromDate !== undefined ? { gte: fromDate } : {}),
74	                ...(beforeDate !== undefined ? { lt: beforeDate } : {}),
75	            };
76	        }
77	        return prisma.gameDay.findMany({
78	            where,
79	            orderBy: [{ date: 'asc' }, { id: 'asc' }],
80	        });
81	    }
82	
83	    /**
84	     * Retrieves the minimum and maximum GameDay IDs for a given year.
85	     *
86	     * @param year - The year to filter GameDays by. If `0` or negative, no date
