1	import type { GameDayStatus, TeamName } from 'prisma/zod/schemas';
2	
3	import type { PointsValue } from '@/types/Points';
4	
5	export type GameWinner = TeamName | 'draw' | null;
6	export type TeamResultState = 'win' | 'loss' | 'draw' | 'unset';
7	
8	/**
9	 * Derives the game winner directly from GameDay.status.
10	 * @param status - The game day's status.
11	 * @returns The game winner ('A', 'B', or 'draw'), or null if the game hasn't
12	 * been decided (Scheduled or NoGame).
13	 */
14	export const getGameWinnerFromStatus = (status: GameDayStatus): GameWinner => {
15	    switch (status) {
16	        case 'AWin':
17	            return 'A';
18	        case 'BWin':
19	            return 'B';
20	        case 'Draw':
21	            return 'draw';
22	        default:
23	            return null;
24	    }
25	};
26	
27	/**
28	 * Derives a player's match points from the game's status and their team.
29	 * @param status - The game day's status.
30	 * @param team - The player's team for that game day, or null if unassigned.
31	 * @returns 0 (loss), 1 (draw), or 3 (win), or null if there is no team
32	 * assignment or the game hasn't been decided.
33	 */
34	export const getPlayerPoints = (
35	    status: GameDayStatus,
36	    team: TeamName | null,
37	): PointsValue | null => {
38	    if (team === null) return null;
39	
40	    switch (status) {
41	        case 'AWin':
42	            return team === 'A' ? 3 : 0;
43	        case 'BWin':
44	            return team === 'B' ? 3 : 0;
45	        case 'Draw':
46	            return 1;
47	        default:
48	            return null;
49	    }
50	};
51	
52	/**
53	 * Whether a game day represents an actual match, as opposed to a
54	 * not-yet-scheduled or cancelled slot.
55	 * @param status - The game day's status.
56	 * @returns True unless the status is NoGame.
57	 */
58	export const isGame = (status: GameDayStatus): boolean => status !== 'NoGame';
59	
60	/**
61	 * Whether a game day's result has been decided.
62	 * @param status - The game day's status.
63	 * @returns True for AWin, BWin, or Draw.
64	 */
65	export const isDecided = (status: GameDayStatus): boolean =>
66	    status === 'AWin' || status === 'BWin' || status === 'Draw';
67	
68	/**
69	 * Determines the result state for a specific team based on the game winner.
70	 *
71	 * @param team - The name of the team to check the result for
72	 * @param winner - The winner of the game (can be a team name, 'draw', or null)
73	 * @returns The result state for the specified team:
74	 *   - 'unset' if the winner is null (game not yet decided)
75	 *   - 'draw' if the game ended in a draw
76	 *   - 'win' if the specified team won
77	 *   - 'loss' if the specified team lost
78	 */
79	export const getTeamResultState = (
80	    team: TeamName,
81	    winner: GameWinner,
82	): TeamResultState => {
83	    if (winner === null) return 'unset';
84	    if (winner === 'draw') return 'draw';
85	    if (winner === team) return 'win';
86	    return 'loss';
87	};
