21	const findElement = (node: unknown, displayName: string): AnyElement | null => {
22	    if (!node || typeof node !== 'object') return null;
23	    const el = node as AnyElement;
24	    if (typeof el.type === 'function') {
25	        const fn = el.type as { displayName?: string; name?: string };
26	        const name = fn.displayName ?? fn.name;
27	        if (name === displayName) return el;
28	    }
29	    const children = (el.props as { children?: unknown }).children;
30	    if (Array.isArray(children)) {
31	        for (const child of children) {
32	            const found = findElement(child, displayName);
33	            if (found) return found;
34	        }
35	    }
36	    return findElement(children, displayName);
37	};
