5	import { ConflictError } from '@/lib/errors';
6	import { isDecided } from '@/lib/gameResult';
7	import gameDayService from '@/services/GameDay';
8	import type { UpdateInvoiceGameDaysInputSchema } from '@/types/actions/UpdateInvoiceGameDays';
9	
10	type UpdateInvoiceGameDaysInput = z.infer<
11	    typeof UpdateInvoiceGameDaysInputSchema
12	>;
13	
14	interface UpdateInvoiceGameDaysDeps {
15	    gameDayService: Pick<typeof gameDayService, 'get' | 'update'>;
16	}
17	
18	const defaultDeps: UpdateInvoiceGameDaysDeps = { gameDayService };
19	
20	/**
21	 * Updates the game/no-game status of a set of game days in parallel.
22	 *
23	 * @param data - Validated input containing game day ids and their scheduled status.
24	 * @param deps - Injectable service dependencies for testing.
25	 * @throws {ConflictError} If any of the game days already has a decided
26	 * result (AWin/BWin/Draw) — this endpoint only toggles whether a game is
27	 * scheduled, and overwriting a decided game day's status here would silently
28	 * discard its recorded result.
29	 */
30	export async function updateInvoiceGameDaysCore(
31	    data: UpdateInvoiceGameDaysInput,
32	    deps: UpdateInvoiceGameDaysDeps = defaultDeps,
33	): Promise<void> {
34	    const existingGameDays = await Promise.all(
35	        data.gameDays.map((gd) => deps.gameDayService.get(gd.id)),
36	    );
37	
38	    const decidedGameDayIds = existingGameDays
39	        .filter((gameDay) => gameDay != null && isDecided(gameDay.status))
40	        .map((gameDay) => gameDay!.id);
41	
42	    if (decidedGameDayIds.length > 0) {
43	        throw new ConflictError(
44	            `Cannot change the scheduled status of game day(s) with a recorded result: ${decidedGameDayIds.join(', ')}.`,
45	            {
46	                details: { gameDayIds: decidedGameDayIds },
47	                publicMessage:
48	                    'One or more of these game days already has a recorded result and cannot be changed here.',
49	            },
50	        );
51	    }
52	
53	    await Promise.all(
54	        data.gameDays.map((gd) =>
55	            deps.gameDayService.update({
56	                id: gd.id,
57	                status: gd.gameScheduled ? 'Scheduled' : 'NoGame',
58	            }),
59	        ),
60	    );
61	}
